private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (i >= bb.limit()) {
        return i;
    }
    int b0 = bb.get(i) & 0xFF;
    // 1-byte ASCII
    if ((b0 & 0x80) == 0) {
        sb.append((char) b0);
        return i + 1;
    }
    // 2-byte sequence
    if ((b0 & 0xE0) == 0xC0) {
        if (i + 1 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int b1 = bb.get(i + 1) & 0xFF;
        if ((b1 & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int codepoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
        sb.append((char) codepoint);
        return i + 2;
    }
    // 3-byte sequence
    if ((b0 & 0xF0) == 0xE0) {
        if (i + 2 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int b1 = bb.get(i + 1) & 0xFF;
        int b2 = bb.get(i + 2) & 0xFF;
        if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80)) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int codepoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
        sb.append((char) codepoint);
        return i + 3;
    }
    // 4-byte sequence
    if ((b0 & 0xF8) == 0xF0) {
        if (i + 3 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int b1 = bb.get(i + 1) & 0xFF;
        int b2 = bb.get(i + 2) & 0xFF;
        int b3 = bb.get(i + 3) & 0xFF;
        if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80) || ((b3 & 0xC0) != 0x80)) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int codepoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        // Convert to surrogate pair
        int high = ((codepoint - 0x10000) >> 10) + 0xD800;
        int low = ((codepoint - 0x10000) & 0x3FF) + 0xDC00;
        sb.append((char) high);
        sb.append((char) low);
        return i + 4;
    }
    // Invalid leading byte
    sb.append('\uFFFD');
    return i + 1;
}

