public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current mapping for the given table (index)
    Mappings current = getMapping(tableName);
    if (current == null) {
        return new Mappings();
    }

    java.util.Map<String, Object> currentProps = current.getProperties();
    java.util.Map<String, Object> historyProps = mappings != null ? mappings.getProperties() : null;
    java.util.Map<String, Object> diffProps = new java.util.LinkedHashMap<>();

    if (currentProps != null) {
        for (java.util.Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String key = entry.getKey();
            // Skip the _source configuration to avoid update conflicts
            if ("_source".equals(key)) {
                continue;
