public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    int len = str.length();
    // Allocate a buffer large enough for the worst case (4 bytes per char)
    byte[] bytes = new byte[len * 4];
    int pos = 0;
    for (int i = 0; i < len; ) {
        int codePoint = str.codePointAt(i);
        i += Character.charCount(codePoint);
        if (codePoint <= 0x7F) {
            bytes[pos++] = (byte) codePoint;
        } else if (codePoint <= 0x7FF) {
            bytes[pos++] = (byte) (0xC0 | (codePoint >> 6));
            bytes[pos++] = (byte) (0x80 | (codePoint & 0x3F));
        } else if (codePoint <= 0xFFFF) {
            bytes[pos++] = (byte) (0xE0 | (codePoint >> 12));
            bytes[pos++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            bytes[pos++] = (byte) (0x80 | (codePoint & 0x3F));
        } else {
            bytes[pos++] = (byte) (0xF0 | (codePoint >> 18));
            bytes[pos++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
            bytes[pos++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            bytes[pos++] = (byte) (0x80 | (codePoint & 0x3F));
        }
    }
    session.writeBytes(bytes, 0, pos);
    return lb;
}

public void removeFromTreeEdgeList() {
    // Remove this edge from the doubly linked list of the first endpoint
    if (treeEdgePrev != null) {
        treeEdgePrev.treeEdgeNext = treeEdgeNext;
    } else {
        // this edge was the head of the list for the first vertex
        from.treeEdgeHead = treeEdgeNext;
    }
    if (treeEdgeNext != null) {
        treeEdgeNext.treeEdgePrev = treeEdgePrev;
    }

    // Remove this edge from the doubly linked list of the second endpoint
    if (treeEdgePrevOpp != null) {
        treeEdgePrevOpp.treeEdgeNextOpp = treeEdgeNextOpp;
    } else {
        // this edge was the head of the list for the second vertex
        to.treeEdgeHead = treeEdgeNextOpp;
    }
    if (treeEdgeNextOpp != null) {
        treeEdgeNextOpp.treeEdgePrevOpp = treeEdgePrevOpp;
    }

    // Null out all references to help GC
