public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Ignore leading '/' if present
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // Split on '/' to get raw segments
    String[] rawSegments = rawPath.split("/", -1); // keep trailing empty segments
    for (String rawSeg : rawSegments) {
        String decodedSeg = rawSeg;
        if (decode) {
            try {
                decodedSeg = java.net.URLDecoder.decode(rawSeg, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(rawSeg, decodedSeg));
    }
    return segments;
}

