public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    int n = desiredCapacity;
    if (n % 2 == 0) n++; // start with an odd number
    while (true) {
        boolean prime = true;
        for (int i = 3; i <= n / i; i += 2) {
            if (n % i == 0) {
                prime = false;
                break;
            }
        }
        if (prime) return n;
        n += 2; // skip even numbers
    }
}

