public final byte[] toByteArray() {
    int totalSize = 0;
    for (Object buf : buffers) {
        if (buf instanceof byte[]) {
            totalSize += ((byte[]) buf).length;
        } else if (buf instanceof java.nio.ByteBuffer) {
            java.nio.ByteBuffer bb = (java.nio.ByteBuffer) buf;
            totalSize += bb.remaining();
        }
    }
    byte[] result = new byte[totalSize];
    int pos = 0;
    for (Object buf : buffers) {
        if (buf instanceof byte[]) {
            byte[] arr = (byte[]) buf;
            System.arraycopy(arr, 0, result, pos, arr.length);
            pos += arr.length;
        } else if (buf instanceof java.nio.ByteBuffer) {
            java.nio.ByteBuffer bb = (java.nio.ByteBuffer) buf;
            int len = bb.remaining();
            bb.get(result, pos, len);
            pos += len;
        }
    }
    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    int hexStart = i + 2;
                    int hexEnd = hexStart;
                    while (hexEnd < len && hexEnd < hexStart + 4) {
                        char h = str.charAt(hexEnd);
                        if ((h >= '0' && h <= '9') ||
                            (h >= 'a' && h <= 'f') ||
                            (h >= 'A' && h <= 'F')) {
                            hexEnd++;
                        } else {
                            break;
                        }
                    }
                    if (hexEnd - hexStart == 4) {
                        String hex = str.substring(hexStart, hexEnd);
                        sb.append((char) Integer.parseInt(hex, 16));
                        i = hexEnd - 1;
                    } else {
                        // Invalid unicode escape, treat literally
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        // Octal escape: up to 3 digits
                        int octStart = i + 1;
                        int octEnd = octStart;
                        int count = 0;
                        while (octEnd < len && count < 3) {
                            char o = str.charAt(octEnd);
                            if (o >= '0' && o <= '7') {
                                octEnd++;
                                count++;
                            } else {
                                break;
                            }
                        }
                        String oct = str.substring(octStart, octEnd);
                        sb.append((char) Integer.parseInt(oct, 8));
                        i = octEnd - 1;
                    } else {
                        // Unknown escape, keep as is
                        sb.append('\\').append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

