protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int removed = 0;
    // If the root itself is inactive, remove the entire tree
    if (!root.isActive()) {
        Deque<Category> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category n = stack.pop();
            removed++;
            for (Category c : n.getChildren()) {
                stack.push(c);
            }
        }
        root = null;
        return removed;
    }
    // Use a stack for depth‑first traversal
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category current = stack.pop();
        List<Category> children = current.getChildren();
        Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                // Count all nodes in this inactive subtree
                Deque<Category> subStack = new ArrayDeque<>();
                subStack.push(child);
                while (!subStack.isEmpty()) {
                    Category n = subStack.pop();
                    removed++;
                    for (Category c : n.getChildren()) {
                        subStack.push(c);
                    }
                }
                it.remove(); // remove the inactive child from its parent
            } else {
                stack.push(child); // process active children later
            }
        }
    }
    return removed;
}

