    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (result > Long.MAX_VALUE / i) {
            throw new ArithmeticException("long overflow");
        }
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Start a circulator at the given start node in the specified direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // Traverse the outer face until we find a node that satisfies the predicate
    // or until we reach the stop node
    while (true) {
        Node current = circ.getNode();
        if (predicate.test(current)) {
            return circ;
        }
        if (current.equals(stop)) {
            return circ;
        }
        circ = circ.next();
    }
}

