public final MatchResult match(CharSequence uri){
    if (uri == null) {
        return null;
    }
    // Assume the pattern template is stored in a field named 'template'
    String templateStr = template;
    String uriStr = uri.toString();

    // Normalize by removing leading/trailing slashes
    if (uriStr.startsWith("/")) {
        uriStr = uriStr.substring(1);
    }
    if (uriStr.endsWith("/")) {
        uriStr = uriStr.substring(0, uriStr.length() - 1);
    }
    if (templateStr.startsWith("/")) {
        templateStr = templateStr.substring(1);
    }
    if (templateStr.endsWith("/")) {
        templateStr = templateStr.substring(0, templateStr.length() - 1);
    }

    // Split into segments
    String[] uriParts = uriStr.isEmpty() ? new String[0] : uriStr.split("/");
    String[] templateParts = templateStr.isEmpty() ? new String[0] : templateStr.split("/");

    // If segment counts differ, no match
    if (uriParts.length != templateParts.length) {
        return null;
    }

    // Map to hold extracted variables
    java.util.Map<String, String> vars = new java.util.HashMap<>();

    for (int i = 0; i < templateParts.length; i++) {
        String tmplSeg = templateParts[i];
        String uriSeg = uriParts[i];
        if (tmplSeg.startsWith("{") && tmplSeg.endsWith("}")) {
            // Variable segment
            String varName = tmplSeg.substring(1, tmplSeg.length() - 1);
            vars.put(varName, uriSeg);
        } else if (!tmplSeg.equals(uriSeg)) {
            // Literal segment mismatch
            return null;
        }
    }

    // Assume MatchResult has a constructor that accepts a Map of variables
    return new MatchResult(vars);
}

