int addConstantNameAndType(final String name, final String descriptor) {
    // Search for an existing CONSTANT_NameAndType_info with the same name and descriptor
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantInfo ci = constantPool.get(i);
        if (ci instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo cnat = (ConstantNameAndTypeInfo) ci;
            if (cnat.getName().equals(name) && cnat.getDescriptor().equals(descriptor)) {
                return i; // Return the existing index
            }
        }
    }
    // Not found – create a new entry and add it to the constant pool
    ConstantNameAndTypeInfo newEntry = new ConstantNameAndTypeInfo(name, descriptor);
    constantPool.add(newEntry);
    return constantPool.size() - 1; // Return the index of the newly added entry
}

private String unescapeId(String input) {
    if (input == null || input.isEmpty()) {
        return input;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    int i = 0;
    while (i < len) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i += 2;
                    break;
                case 't':
                    sb.append('\t');
                    i += 2;
                    break;
                case 'r':
                    sb.append('\r');
                    i += 2;
                    break;
                case 'b':
                    sb.append('\b');
                    i += 2;
                    break;
                case 'f':
                    sb.append('\f');
                    i += 2;
                    break;
                case 'v':
                    sb.append('\u000B');
                    i += 2;
                    break;
                case '0':
                    sb.append('\0');
                    i += 2;
                    break;
                case '\\':
                    sb.append('\\');
                    i += 2;
                    break;
                case '\"':
                    sb.append('\"');
                    i += 2;
                    break;
                case '\'':
                    sb.append('\'');
                    i += 2;
                    break;
                case 'x':
                    if (i + 3 < len) {
                        String hex = input.substring(i + 2, i + 4);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 4;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('x');
                            i += 2;
                        }
                    } else {
                        sb.append('\\').append('x');
                        i += 2;
                    }
                    break;
                case 'u':
                    if (i + 5 < len) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 6;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('u');
                            i += 2;
                        }
                    } else {
                        sb.append('\\').append('u');
                        i += 2;
                    }
                    break;
                case 'U':
                    if (i + 9 < len) {
                        String hex = input.substring(i + 2, i + 10);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append(Character.toChars(val));
                            i += 10;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('U');
                            i += 2;
                        }
                    } else {
                        sb.append('\\').append('U');
                        i += 2;
                    }
                    break;
                default:
                    sb.append(next);
                    i += 2;
                    break;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

