public List<SequenceRange> buildSequenceRanges(){
    java.util.List<SequenceRange> ranges = new java.util.ArrayList<>();
    for (Profile profile : getProfiles()){
        for (Segment segment : profile.getSegments()){
            java.util.List<Snapshot> snapshots = segment.getSnapshots();
            if (snapshots == null || snapshots.isEmpty()){
                continue;
            }
            long min = Long.MAX_VALUE;
            long max = Long.MIN_VALUE;
            for (Snapshot snapshot : snapshots){
                long seq = snapshot.getSequenceNumber();
                if (seq < min) min = seq;
                if (seq > max) max = seq;
            }
            if (min <= max){
                ranges.add(new SequenceRange(min, max));
            }
        }
    }
    return ranges;
}

