private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long running = 0;
    // initialize suffix list with placeholders
    for (int i = 0; i < n; i++) {
        suffix.add(0);
    }
    for (int i = n - 1; i >= 0; i--) {
        running += bounds.get(i);
        suffix.set(i, (int) running);
    }
    return new Pair<>(suffix, running);
}

