    Object msgObj = event.getMessage();
    if (msgObj == null) {
        return Filter.NEUTRAL;
    }
    String msg = msgObj.toString();
    // Example string match condition
    if (msg.contains("match")) {
        return Filter.ACCEPT;
    }
    return Filter.NEUTRAL;
}

