public void putAllWriteable(BeanMap map){
    if (map == null) {
        return;
    }
    java.beans.PropertyDescriptor[] srcPds = map.getPropertyDescriptors();
    for (java.beans.PropertyDescriptor srcPd : srcPds) {
        if (srcPd.getReadMethod() == null) {
            continue; // source property is write‑only
        }
        String name = srcPd.getName();
        Object value;
        try {
            value = map.getProperty(name);
        } catch (IllegalArgumentException e) {
            continue; // property not readable in source
        }
        java.beans.PropertyDescriptor[] destPds = this.getPropertyDescriptors();
        for (java.beans.PropertyDescriptor destPd : destPds) {
            if (destPd.getName().equals(name) && destPd.getWriteMethod() != null) {
                try {
                    this.setProperty(name, value);
                } catch (IllegalArgumentException e) {
                    // ignore write failures
                }
                break;
            }
        }
    }
}

