private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> result = new ArrayList<>();
    // Iterate over all edges in the graph
    for (E e : graph.getEdges()){
        // Get the two endpoints of the edge
        int u = graph.getSource(e);
        int v = graph.getTarget(e);
        // Build the neighborhood of the edge (neighbors of u and v)
        Set<Integer> neighborhood = new HashSet<>();
        neighborhood.addAll(graph.getNeighbors(u));
        neighborhood.addAll(graph.getNeighbors(v));
        neighborhood.remove(u);
        neighborhood.remove(v);
        List<Integer> neighList = new ArrayList<>(neighborhood);
        int n = neighList.size();
        // Enumerate all subsets of the neighborhood up to size 3
        int maxMask = 1 << n;
        for (int mask = 1; mask < maxMask; mask++){
            int subsetSize = Integer.bitCount(mask);
            if (subsetSize > 3) continue;
            // Build the set of vertices to remove
            Set<Integer> removed = new HashSet<>();
            for (int i = 0; i < n; i++){
                if ((mask & (1 << i)) != 0){
                    removed.add(neighList.get(i));
                }
            }
            // Check if removing this set disconnects u and v
            if (isConnected(u, v, removed)) continue; // still connected
            // Check minimality: no proper subset disconnects
            boolean minimal = true;
            for (int sub = (mask - 1) & mask; sub > 0; sub = (sub - 1) & mask){
                if (Integer.bitCount(sub) < subsetSize){
                    Set<Integer> subRemoved = new HashSet<>();
                    for (int i = 0; i < n; i++){
                        if ((sub & (1 << i)) != 0){
                            subRemoved.add(neighList.get(i));
                        }
                    }
                    if (!isConnected(u, v, subRemoved)){
                        minimal = false;
                        break;
                    }
                }
            }
            if (!minimal) continue;
            // Build the separator list as pairs (vertex, vertex)
            List<Pair<Integer,Integer>> separator = new ArrayList<>();
            for (int i = 0; i < n; i++){
                if ((mask & (1 << i)) != 0){
                    int vertex = neighList.get(i);
                    separator.add(new Pair<>(vertex, vertex));
                }
            }
            result.add(new Pair<>(separator, e));
        }
    }
    return result;
}

// Helper method to test connectivity between two vertices while ignoring a set of removed vertices
private boolean isConnected(int start, int target, Set<Integer> removed){
    if (removed.contains(start) || removed.contains(target)) return false;
    Set<Integer> visited = new HashSet<>();
    Queue<Integer> queue = new LinkedList<>();
    queue.add(start);
    visited.add(start);
    while (!queue.isEmpty()){
        int cur = queue.poll();
        if (cur == target) return true;
        for (int nb : graph.getNeighbors(cur)){
            if (removed.contains(nb) || visited.contains(nb)) continue;
            visited.add(nb);
            queue.add(nb);
        }
    }
    return false;
}

