    // Delay repaint to allow the table to paint the newly selected row
    SwingUtilities.invokeLater(() -> table.repaint());
}

public ByteVector putInt(final int intValue){
    int required = pos + 4;
    if (required > buf.length) {
        int newCap = Math.max(buf.length * 2, required);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, buf.length);
        buf = newBuf;
    }
    buf[pos++] = (byte)(intValue >>> 24);
    buf[pos++] = (byte)(intValue >>> 16);
    buf[pos++] = (byte)(intValue >>> 8);
    buf[pos++] = (byte)intValue;
    return this;
}

