public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Assumes the class has a field named 'name' of type String.
    if (name == null) {
        return;
    }
    int len = name.length();
    int start = nameStart;
    if (start < 0) {
        start = 0;
    }
    if (start >= len) {
        return;
    }
    boolean nextInitial = true;
    for (int i = start; i < len; i++) {
        char ch = name.charAt(i);
        if (Character.isLetter(ch)) {
            if (nextInitial) {
                buf.append(Character.toUpperCase(ch));
                buf.append('.');
                nextInitial = false;
            }
        } else {
            nextInitial = true;
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    Type first = bounds[0];
    if (first == null) {
        return Unknown.class;
    }
    if (first instanceof TypeVariable) {
        return resolveBound((TypeVariable<?>) first);
    }
    return first;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V v1 = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V v2 = list.get(j);
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null || keys.isEmpty()){
        return new java.util.ArrayList<>();
    }
    java.util.List<Integer> intKeys = new java.util.ArrayList<>(keys.size());
    for (K k : keys){
        intKeys.add((Integer) k);
    }
    java.util.List<Integer> sorted = new java.util.ArrayList<>(intKeys);
    java.util.Collections.sort(sorted);
    java.util.Map<Integer, Integer> lowerMap = new java.util.HashMap<>();
    Integer lastDistinct = null;
    for (Integer key : sorted){
        if (lastDistinct == null){
            lowerMap.put(key, null);
        } else {
            if (key.equals(lastDistinct)){
                lowerMap.put(key, lastDistinct);
            } else {
                lowerMap.put(key, lastDistinct);
                lastDistinct = key;
            }
        }
        if (lastDistinct == null){
            lastDistinct = key;
        }
    }
    java.util.List<Integer> result = new java.util.ArrayList<>(keys.size());
    for (Integer key : intKeys){
        result.add(lowerMap.get(key));
    }
    return result;
}

