private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return upperBounds;
    }
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        if (key == null) {
            upperBounds.add(Integer.MAX_VALUE);
            continue;
        }
        if (i < keys.size() - 1) {
            K nextKey = keys.get(i + 1);
            if (nextKey instanceof Integer) {
                upperBounds.add((Integer) nextKey);
            } else {
                // Fallback: use hash code as an approximate upper bound
                upperBounds.add(nextKey.hashCode());
            }
        } else {
            upperBounds.add(Integer.MAX_VALUE);
        }
    }
    return upperBounds;
}

