protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getFormattedMessage();
    if (message == null) {
        message = "";
    }
    // Assume a field: Set<PrintWriter> clientWriters; that holds writers for each connected client.
    // Synchronize to avoid concurrent modification.
    synchronized (clientWriters) {
        Iterator<PrintWriter> it = clientWriters.iterator();
        while (it.hasNext()) {
            PrintWriter writer = it.next();
            if (writer == null) {
                continue;
            }
            try {
                writer.println(message);
                writer.flush();
            } catch (Exception e) {
                // If writing fails, remove this writer from the set to avoid future errors.
                it.remove();
            }
        }
    }
}

public static String toString(final char ch) {
    // Cache for ASCII 7-bit characters (0-127)
    // The cache array is lazily initialized on first use.
    if (ch < 128) {
        // Use a static cache array; initialize if necessary
        // The array is declared as a private static field in the class.
        // We assume it exists: private static final String[] ASCII_CACHE = new String[128];
        if (ASCII_CACHE[ch] == null) {
            ASCII_CACHE[ch] = new String(new char[]{ch});
        }
        return ASCII_CACHE[ch];
    }
    // For non-ASCII characters, simply create a new String
    return Character.toString(ch);
}

