public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (true) {
        int b = input.read();
        if (b == -1) {
            if (shift == 0) {
                return 0; // EOF before any byte read
            } else {
                throw new IOException("Unexpected EOF while reading tag");
            }
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            if (tag == 0) {
                throw new IOException("Invalid tag 0");
            }
            return tag;
        }
        shift += 7;
        if (shift >= 32) {
            throw new IOException("Malformed varint");
        }
    }
}

