}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) {
                if (sb.length() > 0) {
                    ThreadSnapshot ts = ThreadSnapshot.parseFromString(sb.toString());
                    boolean inRange = false;
                    for (ProfileAnalyzeTimeRange r : timeRanges) {
                        if (ts.getTimestamp() >= r.getStartTime() && ts.getTimestamp() <= r.getEndTime()) {
                            inRange = true;
                            break;
                        }
                    }
                    if (inRange) {
                        result.add(ts);
                    }
                    sb.setLength(0);
                }
            } else {
                sb.append(line).append("\n");
            }
        }
        if (sb.length() > 0) {
            ThreadSnapshot ts = ThreadSnapshot.parseFromString(sb.toString());
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange r : timeRanges) {
                if (ts.getTimestamp() >= r.getStartTime() && ts.getTimestamp() <= r.getEndTime()) {
                    inRange = true;
                    break;
                }
            }
            if (inRange) {
                result.add(ts);
            }
        }
    }
    return result;
}
